#include <stdio.h>
#define CHECK(c) do{if(!(c)){fprintf(stderr,"FAIL line %d: %s\n",__LINE__,#c);return 1;}}while(0)
static int restore_fixture(const double* s,void** handle){dango_belt_config cfg={0};cfg.node_count=(int)s[87];cfg.substep_count=(int)s[88];float* p=&cfg.radial_rest_length;for(int i=0;i<39;++i)p[i]=(float)s[89+i];float cal[11];for(int i=0;i<11;++i)cal[i]=(float)s[128+i];
 int result=dango_belt_create_calibrated(&cfg,0,0,(int)s[81],cal,11,handle);if(result)return result;belt_body* b=belt_lookup(*handle);memcpy(b->q,s+2,sizeof b->q);memcpy(b->v,s+38,sizeof b->v);b->radius=s[74];b->scale=s[75];b->left=s[76];b->right=s[77];b->ramp=s[78];b->cooldown=s[79];b->drag_theta=s[80];b->short_bones=(int)s[81];b->grounded=(int)s[82];b->dragging=(int)s[83];b->original_ground_jump=(int)s[84];b->has_stepped=(int)s[85];b->shape_guard=(int)s[86];for(int i=0;i<11;++i)b->cal[i]=s[128+i];b->guard[2]=b->solver_diag[1]=s[139];memcpy(b->mass,s+140,sizeof b->mass);b->speed_saturation=(int)s[176];return 0;
}

static int field_contract(void){
 void* h=NULL;CHECK(restore_fixture(solver_snapshot_0,&h)==0);belt_body* b=belt_lookup(h);memset(b->q,0,sizeof b->q);b->q[2]=b->q[5]=b->radius;b->whale_gain=.6;
 double f[BELT_D]={0},other[BELT_D]={0};CHECK(belt_whale_force(b,f));CHECK(b->whale_diag[9]>0&&b->whale_diag[10]>0);CHECK(fabs(f[0])<1e-12&&fabs(f[1])<1e-12&&f[34]==0&&f[35]==0);double torque=0;for(int j=0;j<BELT_D;j+=2)torque+=b->q[j]*f[j+1]-b->q[j+1]*f[j];CHECK(fabs(torque)<1e-12);CHECK(b->whale_diag[5]<1e-12&&b->whale_diag[6]<1e-12&&b->whale_diag[7]<1e-12);
 b->whale_gain=-.6;CHECK(belt_whale_force(b,other));/* On the symmetric circle, reflection x -> -x also reverses material theta. */
 for(int i=0;i<64;++i){belt_v a=belt_eval(f,2*BELT_PI*i/64,0),z=belt_eval(other,BELT_PI-2*BELT_PI*i/64,0);CHECK(fabs(a.x+z.x)<1e-11&&fabs(a.y-z.y)<1e-11);}
 memset(b->q,0,sizeof b->q);memset(f,0,sizeof f);CHECK(!belt_whale_force(b,f));for(int j=0;j<BELT_D;++j)CHECK(f[j]==0);CHECK(dango_belt_destroy(h)==0);puts("zero total force/torque, mirrored field and bounded degenerate rejection PASS");return 0;
}
static int gain_contract(void){void* h=NULL;CHECK(restore_fixture(solver_snapshot_0,&h)==0);belt_body* b=belt_lookup(h);b->grounded=1;b->dragging=0;b->ramp=0;b->whale_gain=0;float c[9]={1};double f[BELT_D]={0},hstep=.001;
 for(int i=0;i<150;++i){double before=b->whale_gain;memset(f,0,sizeof f);CHECK(belt_whale_update(b,hstep,c,false,0,f));CHECK(b->whale_gain>=before&&b->whale_gain-before<=hstep/.15+1e-15);}CHECK(fabs(b->whale_gain-1)<1e-12);
 c[0]=-1;for(int i=0;i<300;++i){double before=b->whale_gain;memset(f,0,sizeof f);CHECK(belt_whale_update(b,hstep,c,false,0,f));CHECK(before-b->whale_gain<=hstep/.15+1e-15);}CHECK(fabs(b->whale_gain+1)<1e-12);c[0]=0;for(int i=0;i<200;++i){double before=b->whale_gain;memset(f,0,sizeof f);CHECK(belt_whale_update(b,hstep,c,false,0,f));CHECK(b->whale_gain-before<=hstep/.20+1e-15);}CHECK(fabs(b->whale_gain)<1e-12);
 for(int mode=0;mode<8;++mode){memset(c,0,sizeof c);c[0]=1;b->grounded=mode!=0;b->dragging=mode==1;b->ramp=mode==5?.001:0;c[1]=mode==3?1.0f:0.0f;c[6]=mode==4?1.0f:0.0f;c[8]=mode==7?1.0f:0.0f;b->whale_gain=.5;memset(f,0,sizeof f);CHECK(belt_whale_update(b,hstep,c,mode==2,mode==6?1:0,f));for(int j=0;j<BELT_D;++j)CHECK(f[j]==0);CHECK(b->whale_diag[11]!=0);if(mode==7)CHECK(b->whale_gain==0);}
 memset(c,0,sizeof c);c[0]=1;b->grounded=1;b->dragging=0;b->ramp=0;b->v[34]=b->cfg.maximum_horizontal_speed+1;memset(f,0,sizeof f);CHECK(belt_whale_update(b,hstep,c,false,0,f));CHECK(b->whale_diag[11]==0&&f[2]!=0);CHECK(dango_belt_destroy(h)==0);puts("gain start/release/reversal, all suppression, recovery and independent vx gate PASS");return 0;}
static int abi_contract(void){void* h=NULL;CHECK(restore_fixture(solver_snapshot_0,&h)==0);belt_body* fixture=belt_lookup(h);dango_belt_config cfg=fixture->cfg;CHECK(dango_belt_destroy(h)==0);CHECK(dango_belt_create(&cfg,0,0,1,&h)==0);belt_body* b=belt_lookup(h);CHECK(!b->whale_drive&&b->whale_gain==0);CHECK(dango_belt_set_whale_drive(h,1)==-600);CHECK(dango_belt_set_shape_guard(h,1)==0);CHECK(dango_belt_set_whale_drive(h,2)==-600);CHECK(dango_belt_set_whale_drive(h,1)==0);CHECK(dango_belt_set_shape_guard(h,0)==-600);CHECK(dango_belt_set_speed_saturation(h,1)==0);double s[201],d[17];for(int i=0;i<201;++i)s[i]=123;for(int i=0;i<17;++i)d[i]=456;CHECK(dango_belt_read_snapshot(h,s,199)==-600&&s[0]==123);CHECK(dango_belt_read_snapshot(h,s,200)==0&&s[177]==1&&s[178]==0&&s[200]==123);CHECK(dango_belt_read_whale_drive(h,d,15)==-600&&d[0]==456);CHECK(dango_belt_read_whale_drive(h,d,16)==0&&d[16]==456&&d[0]==1&&d[1]==1);float c[9]={0};CHECK(dango_belt_step(h,.0166666f,c,9)==0);CHECK(dango_belt_set_whale_drive(h,0)==-600);CHECK(dango_belt_destroy(h)==0);CHECK(dango_belt_set_whale_drive(h,0)==-601);puts("optional ABI dependency/lifetime/capacity/snapshot contracts PASS");return 0;}
static int integration_contract(void){void* h=NULL;CHECK(restore_fixture(solver_snapshot_0,&h)==0);belt_body* b=belt_lookup(h);b->whale_drive=1;b->speed_saturation=1;b->grounded=1;b->dragging=0;b->ramp=0;float c[9]={1};int result=dango_belt_step(h,.0166666f,c,9);if(result)printf("whale integration fail site %.0f\n",b->solver_diag[3]);CHECK(result==0);CHECK(b->whale_diag[4]>0&&b->whale_diag[9]>0&&b->whale_diag[8]!=0);double lhs=b->diag[3]+b->diag[5]+b->diag[7]-b->diag[2]-b->diag[4]-b->diag[6],rhs=b->diag[25]+b->diag[10]+b->diag[11]+b->diag[27]+b->diag[28]+b->diag[14]+b->diag[15]+b->diag[18]+b->diag[7]-b->diag[6];CHECK(fabs(lhs-rhs)<1e-8*(1+fabs(lhs)));CHECK(b->stats[56]<=40&&b->solver_diag[6]<20&&b->stats[34]<=2e-7&&b->guard[4]<=131072);
 /* Rejected initial certificate restores physical state, gain and whale telemetry. */
 b->speed_saturation=0;b->cfg.maximum_speed=.000001f;belt_body before=*b;CHECK(dango_belt_step(h,.0166666f,c,9)<0);CHECK(b->solver_diag[3]==13);CHECK(memcmp(before.q,b->q,sizeof b->q)==0&&memcmp(before.v,b->v,sizeof b->v)==0&&before.whale_gain==b->whale_gain);CHECK(b->whale_diag[2]==before.whale_diag[2]+1);b->whale_diag[2]=before.whale_diag[2];CHECK(memcmp(before.whale_diag,b->whale_diag,sizeof b->whale_diag)==0);CHECK(dango_belt_destroy(h)==0);puts("active integration, unchanged gates, external energy ledger and atomic rollback PASS");return 0;}
static int off_contract(void){void* a=NULL;void* z=NULL;CHECK(restore_fixture(solver_snapshot_0,&a)==0);CHECK(restore_fixture(solver_snapshot_0,&z)==0);belt_body* b=belt_lookup(z);b->has_stepped=0;CHECK(dango_belt_set_whale_drive(z,0)==0);b->has_stepped=belt_lookup(a)->has_stepped;float c[9]={1};for(int i=0;i<6;++i){CHECK(dango_belt_step(a,.0166666f,c,9)==0);CHECK(dango_belt_step(z,.0166666f,c,9)==0);belt_body* x=belt_lookup(a);CHECK(memcmp(x->q,b->q,sizeof b->q)==0&&memcmp(x->v,b->v,sizeof b->v)==0&&memcmp(x->stats,b->stats,sizeof b->stats)==0&&memcmp(x->diag,b->diag,sizeof b->diag)==0);}CHECK(dango_belt_destroy(a)==0&&dango_belt_destroy(z)==0);puts("default and explicitly disabled byte-identical trajectory PASS");return 0;}
